'use strict';

/**
 * Leave out "Translate" when what is shown is, beyond reasonable doubt, already
 * in the reader's language (owner, 31 Oct 2026). The detector is the website's
 * own (textLanguage.js, generated by scripts/sync-text-language.mjs), so both
 * sites decide alike. Doubt keeps the button.
 */

const { isClearlyWrittenIn, vocabularyCode, vocabularySet } = require('./textLanguage');

const vocabularies = new Map();

function vocabularyFor(locale) {
  const code = vocabularyCode(locale);
  if (!code) return null;
  if (!vocabularies.has(code)) {
    let set = null;
    try {
      set = vocabularySet(require(`./vocabulary/${code}.json`));
    } catch {
      set = null; // Missing list: the button stays.
    }
    vocabularies.set(code, set);
  }
  return vocabularies.get(code);
}

/** True when every part shown is clearly in `locale` already. */
function alreadyInLanguage(parts, locale) {
  const list = (Array.isArray(parts) ? parts.flat(Infinity) : [parts])
    .map((part) => (part === null || part === undefined ? '' : String(part)));
  return isClearlyWrittenIn(list, locale, vocabularyFor(locale));
}

/** The opposite, for templates: should a Translate control be offered? */
function translationNeeded(parts, locale) {
  return !alreadyInLanguage(parts, locale);
}

module.exports = { alreadyInLanguage, translationNeeded };
